  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "IF_core_m_dense_in_rNoSig_buffer_enqw_whas__79_ETC___d791", 259u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "IF_core_m_dense_in_rNoSig_buffer_ff_i_notEmpty_ETC___d792", 259u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "IF_core_m_dense_in_wNoSig_buffer_enqw_whas__71_ETC___d1255", 289u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
